do $$declare ddl text;begin ddl:=pg_get_functiondef('public.get_live_shift_status(uuid[])'::regprocedure);ddl:=replace(ddl,$a$select work_date into d from public.attendance_clock_sessions where employee_id=emp and state in('working','on_break')$a$,$b$select s.work_date into d from public.attendance_clock_sessions s where s.employee_id=emp and s.state in('working','on_break')$b$);execute ddl;end $$;
